SELECT band, count() AS spots, countIf(snr + (50 - power) >= 10) AS v10, countIf(snr + (50 - power) >= 13) AS v13, countIf(snr + (50 - power) >= 13 AND distance >= 50) AS v13_sky, uniqExactIf((tx_sign, rx_sign), snr + (50 - power) >= 13 AND distance >= 50) AS pairs13_sky, uniqExactIf(toHour(time), snr + (50 - power) >= 13 AND distance >= 50) AS hours13_sky FROM wspr.rx WHERE time >= '2026-10-05 00:00:00' AND time < '2026-10-06 00:00:00' AND distance < 400 AND rx_lat BETWEEN 24 AND 50 AND rx_lon BETWEEN -125 AND -66 AND tx_lat BETWEEN 24 AND 50 AND tx_lon BETWEEN -125 AND -66 GROUP BY band ORDER BY band FORMAT TSVWithNames
